INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4872019', 'Battle of Peshawar', 'The Battle of Peshawar was fought on 27 November 1001 between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Jayapala, near Peshawar. Jayapala was defeated and captured, and as a result of the humiliation of the defeat, he later immolated himself in a funeral pyre.', 1001, 11, 27, NULL, NULL, NULL, 'day', '27 November 1001', 50, 'https://en.wikipedia.org/wiki/Battle_of_Peshawar_(1001)'),
  ('Q4871308', 'Battle of Jamrud', 'The Battle of Jamrud was fought between the forces of the Emirate of Afghanistan under Wazir Akbar Khan, and the Sikh Empire under Maharaja Ranjit Singh on 30 April 1837. The Afghans confronted the Sikh forces at Jamrud.', 1837, 4, 30, NULL, NULL, NULL, 'day', '30 April 1837', 47, 'https://en.wikipedia.org/wiki/Battle_of_Jamrud'),
  ('Q3246392', 'Battle of Miani', 'The Battle of Miani (Sindhi: مياڻي جي جنگ), also known as the Battle of Meeanee, was a battle between a British army under Charles James Napier and the Talpur army of Sindh, composed mainly of Baloch troops under the Talpur Amirs. led by Amir Nasir Khan Talpur.', 1843, 2, 17, NULL, NULL, NULL, 'day', '17 February 1843', 43, 'https://en.wikipedia.org/wiki/Battle_of_Miani'),
  ('Q1761867', 'Battle of Ramnagar', 'The Battle of Ramnagar (sometimes referred to as the Battle of Rumnuggur) was fought on 22 November 1848 between the forces of the British Empire (including the British East India Company) and the Sikh Empire during the Second Anglo-Sikh War. The British were led by Sir Hugh Gough, while the Sikhs were led by Raja Sher Singh Attariwalla.', 1848, 11, 22, NULL, NULL, NULL, 'day', '22 November 1848', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ramnagar'),
  ('Q4870727', 'Battle of Chillianwala', 'The Battle of Chillianwala (also spelled Chillianwallah) was fought in January 1849 during the Second Anglo-Sikh War in the Chillianwala region (Mandi Bahauddin) of Punjab, now part of Pakistan. The battle was one of the bloodiest fought by the British East India Company.', 1849, 1, 13, NULL, NULL, NULL, 'day', '13 January 1849', 47, 'https://en.wikipedia.org/wiki/Battle_of_Chillianwala'),
  ('Q4871164', 'Battle of Gujrat', 'The Battle of Gujrat was a decisive battle in the Second Anglo-Sikh War, fought on 21 February 1849, between the forces of the East India Company, and a Sikh army in rebellion against the company''s control of the Sikh Empire, represented by the child Maharaja Duleep Singh who was in British custody in Lahore. The Sikh army was defeated by the British regular and Bengal Army forces of the British East India Company.', 1849, 2, 21, NULL, NULL, NULL, 'day', '21 February 1849', 45, 'https://en.wikipedia.org/wiki/Battle_of_Gujrat'),
  ('Q64879', 'Siege of Malakand', 'The siege of Malakand was the 26 July – 2 August 1897 siege of the British garrison in the Malakand region of colonial British India''s North West Frontier Province. The British faced a force of Pashtun tribesmen whose tribal lands had been bisected by the Durand Line, the 1,519 mile (2,445 km) border between Afghanistan and British India drawn up at the end of the Anglo-Afghan wars to help hold back what the British feared to be the Russian Empire''s spread of influence towards the Indian subcontinent.', 1897, 7, 26, 1897, 8, 2, 'day', '26 July 1897 – 2 August 1897', 52, 'https://en.wikipedia.org/wiki/Siege_of_Malakand'),
  ('Q383067', 'Battle of Saragarhi', 'The Battle of Saragarhi was a last-stand battle fought before the Tirah Campaign between the British Indian Empire and Afghan tribesmen. On 12 September 1897, an estimated 12,000–24,000 Orakzai and Afridi tribesmen were seen near Gogra, at Samana Suk, and around Saragarhi, cutting off Fort Gulistan from Fort Lockhart.', 1897, 9, 12, NULL, NULL, NULL, 'day', '12 September 1897', 61, 'https://en.wikipedia.org/wiki/Battle_of_Saragarhi'),
  ('Q7267930', 'Qissa Khwani massacre', 'The Qissa Khwani massacre (Pashto: د قصه خوانۍ بازار خوڼۍ پېښه) in Peshawar, North-West Frontier Province, British India (modern day Khyber Pakhtunkhwa, Pakistan) on 23 April 1930 was an armoured vehicle-ramming attack and mass shooting of the unarmed civilian freedom fighters by the British colonial troops, which consequently became one of the defining moments of the independence movement in British India. It was the first major confrontation between the British Indian Army and demonstrators in the city belonging to Abdul Ghaffar Khan''s non-violent Khudai Khidmatgar (servants of God)…', 1930, 4, 23, NULL, NULL, NULL, 'day', '23 April 1930', 39, 'https://en.wikipedia.org/wiki/Qissa_Khwani_massacre'),
  ('Q2614092', '1945 Balochistan earthquake', 'The 1945 Balochistan earthquake occurred in British India at 1:26 PKT on 28 November 1945 with a moment magnitude of 8.1 on the Richter scale and a maximum perceived intensity of X (Extreme) on the Mercalli intensity scale.', 1945, 11, 27, NULL, NULL, NULL, 'day', '27 November 1945', 45, 'https://en.wikipedia.org/wiki/1945_Balochistan_earthquake'),
  ('Q1413732', 'Kashmir conflict', 'The Kashmir conflict is a territorial conflict over the Kashmir region, primarily between India and Pakistan, and also between China and India in the northeastern portion of the region. The conflict started after the partition of India in 1947 as both India and Pakistan claimed the entirety of the former princely state of Jammu and Kashmir.', 1947, NULL, NULL, NULL, NULL, NULL, 'year', '1947', 78, 'https://en.wikipedia.org/wiki/Kashmir_conflict'),
  ('Q7140651', '1947 Rawalpindi massacres', 'The Rawalpindi Massacres (also Rawalpindi riots) refer to widespread violence, including large-scale massacres and rapes, against Hindus and Sikhs by Muslim mobs in the Rawalpindi Division of the Punjab Province of British India in March 1947. The violence preceded the partition of India and was instigated and perpetrated by the Muslim League National Guards, a quasi-paramilitary organisation affiliated with the Muslim League, as well as Muslim League''s local cadres and politicians, demobilised Muslim soldiers, local officials and policemen.', 1947, 3, NULL, NULL, NULL, NULL, 'month', 'March 1947', 41, 'https://en.wikipedia.org/wiki/Rawalpindi_Massacres'),
  ('Q590605', 'insurgency in Balochistan', 'An ongoing insurgency in Pakistan''s Balochistan province and Iran''s Sistan and Baluchestan province is fought between Baloch nationalist separatist groups, Islamist militants, and the governments of Pakistan and Iran. The conflict is rooted in long-standing grievances over political marginalisation, economic underdevelopment, enforced disappearances, and the control of Balochistan''s natural resources.', 1948, NULL, NULL, NULL, NULL, NULL, 'year', '1948', 65, 'https://en.wikipedia.org/wiki/Insurgency_in_Balochistan'),
  ('Q4114551', '1958 Pakistani coup d''état', 'The 1958 Pakistani military coup was the first military coup in Pakistan that took place on 27 October 1958. It resulted in the toppling of Iskander Ali Mirza, the president of Pakistan, by Muhammad Ayub Khan, the commander-in-chief of the Pakistan Army.', 1958, 10, 27, 1958, 10, 27, 'day', '27 October 1958', 50, 'https://en.wikipedia.org/wiki/1958_Pakistani_military_coup'),
  ('Q65044752', 'Therhi Massacre', 'The Therhi massacre was a mass murder that occurred on 3 June 1963 in Therhi, Sindh, Pakistan. In it, 118 Shia Muslims were killed by a mob of Sunni Deobandi Muslims.', 1963, 6, 3, NULL, NULL, NULL, 'day', '3 June 1963', 39, 'https://en.wikipedia.org/wiki/Therhi_massacre'),
  ('Q4870594', 'Battle of Burki', 'The Battle of Burki (also known as the Battle of Lahore) was a battle between the Indian and Pakistan Army during the Indo-Pakistani War of 1965 at Burki, a village that lies 11 km south-east of Lahore, Pakistan near the border with India and which is connected to Lahore by a bridge over the Bambawali-Ravi-Bedian Canal (BRB Canal). During the battle, Indian infantry clashed with Pakistani forces that were entrenched in pillboxes, dug-outs and slit trenches that had been carved into the canal banks.', 1965, 9, 11, NULL, NULL, NULL, 'day', '11 September 1965', 37, 'https://en.wikipedia.org/wiki/Battle_of_Burki'),
  ('Q4870720', 'Battle of Gujranwala', 'The Battle of Chawinda was a major engagement between Pakistan and India during the Indo-Pakistani war of 1965 as part of the Sialkot campaign. It is well known as being one of the largest tank battles in history since the Battle of Kursk, which was fought between the Soviet Union and Nazi Germany in World War II. The initial clashes in Chawinda coincided with the Battle of Phillora, and the fighting here intensified once the Pakistani forces at Phillora retreated.', 1965, 9, 14, NULL, NULL, NULL, 'day', '14 September 1965', 39, 'https://en.wikipedia.org/wiki/Battle_of_Chawinda'),
  ('Q4114552', '1977 Pakistani military coup', 'The 1977 Pakistani military coup (codenamed Operation Fair Play) was the second military coup in the history of Pakistan. Taking place on 5 July 1977, it was carried out by Muhammad Zia-ul-Haq, the chief of army staff, overthrowing the government of Prime Minister Zulfikar Ali Bhutto.', 1977, 7, 5, NULL, NULL, NULL, 'day', '5 July 1977', 43, 'https://en.wikipedia.org/wiki/1977_Pakistani_military_coup'),
  ('Q4393810', 'Pakistani Islamisation programme referendum, 1984', 'A referendum on the Islamisation policy of President Muhammad Zia-ul-Haq was held in Pakistan on 19 December 1984. Voters were asked whether they supported Zia-ul-Haq''s proposals for amending several laws in accordance with the Quran and Sunnah, whether they wanted this process to continue, and whether they supported the Islamist ideology of Pakistan.', 1984, 12, 19, NULL, NULL, NULL, 'day', '19 December 1984', 43, 'https://en.wikipedia.org/wiki/1984_Pakistani_Islamisation_programme_referendum'),
  ('Q2907585', 'Pan Am Flight 73', 'Pan Am Flight 73 was a scheduled passenger flight operated by Pan American World Airways from Bombay to New York City via Karachi and Frankfurt. On 5 September 1986, the Boeing 747-100 serving the flight, with 379 passengers and crew on board, was hijacked while on the ground at Karachi by four armed Palestinian militants affiliated with the Abu Nidal Organization.', 1986, 9, 5, NULL, NULL, NULL, 'day', '5 September 1986', 59, 'https://en.wikipedia.org/wiki/Pan_Am_Flight_73'),
  ('Q404517', 'Kargil War', 'The Kargil War, also known as the Kargil conflict, was fought between India and Pakistan from May to July 1999 in the Kargil district of Ladakh, then part of the Indian-administered state of Jammu and Kashmir and along the Line of Control (LoC). In India, the conflict is also referred to as Operation Vijay (lit. ''Victory''), which was the codename of the Indian military operation in the region.', 1999, NULL, NULL, 1999, 7, 26, 'year', '1999', 76, 'https://en.wikipedia.org/wiki/Kargil_War'),
  ('Q2352036', '1999 Pakistani coup d''état', 'The 1999 military takeover in Pakistan was a bloodless coup d''état initiated by the military staff at the Joint Staff HQ working under the Chairman of the Joint Chiefs of Staff Committee and Chief of Army Staff General Pervez Musharraf. The instigators seized control of the civilian government of the popularly elected Prime Minister Nawaz Sharif on 12 October 1999.', 1999, 10, 12, NULL, NULL, NULL, 'day', '12 October 1999', 55, 'https://en.wikipedia.org/wiki/1999_Pakistani_coup_d''%C3%A9tat'),
  ('Q179275', 'insurgency in Khyber Pakhtunkhwa', 'Since 2004, an insurgency has been fought in the Pakistani province of Khyber Pakhtunkhwa by Islamist militant groups such as the Tehrik-i-Taliban Pakistan (TTP), Jundallah, Lashkar-e-Islam (LeI), the Tehreek-e-Nafaz-e-Shariat-e-Mohammadi (TNSM), Al-Qaeda, and their Central Asian allies such as the Islamic State – Khorasan Province (ISKP), Islamic Movement of Uzbekistan, East Turkistan Movement, Jamaat-ul-Ahrar, Ittihad-ul-Mujahideen Pakistan, and elements of organised crime. Before being transformed into an insurgency in 2017, the conflict was a war.', 2004, 3, 16, NULL, NULL, NULL, 'day', '16 March 2004', 70, 'https://en.wikipedia.org/wiki/Insurgency_in_Khyber_Pakhtunkhwa'),
  ('Q2497334', 'Battle of Wana', 'The Battle of Wana was a March 2004 military engagement between the Pakistan Army and members of Osama Bin Laden''s al-Qaeda at Azam Warsak, near the South Waziristan town of Wana. The army troops and intelligence paramilitary soldiers faced an estimated ~500 al-Qaeda foreign fighters holed up in several fortified settlements.', 2004, 3, 16, 2004, 3, 23, 'day', '16 March 2004 – 23 March 2004', 43, 'https://en.wikipedia.org/wiki/Battle_of_Wana'),
  ('Q210137', '2005 Kashmir earthquake', 'On 8 October 2005, at 08:50:39 PKT, a Mw 7.6 earthquake struck the Azad Kashmir region in northern Pakistan. Its epicenter was located in the tehsil of Patikka, near the city of Muzaffarabad.', 2005, 10, 8, NULL, NULL, NULL, 'day', '8 October 2005', 75, 'https://en.wikipedia.org/wiki/2005_Kashmir_earthquake'),
  ('Q2621757', 'Lal Masjid Siege', 'The siege of Lal Masjid (Urdu: لال مسجد محاصرہ; code-named Operation Sunrise initially code-named as Operation Silence) was an armed confrontation in July 2007 between a Islamist fundamentalist private militia and the government of Pakistan, led by president Pervez Musharraf and prime minister Shaukat Aziz. The focal points of the operation were the Lal Masjid ("Red Mosque") and the Jamia Hafsa madrasah complex in Islamabad, Pakistan.', 2007, 7, 3, 2007, 7, 11, 'day', '3 July 2007 – 11 July 2007', 48, 'https://en.wikipedia.org/wiki/Siege_of_Lal_Masjid'),
  ('Q3041128', 'First Battle of Swat', 'The First Battle of Swat (code-named Operation Rah-e-Haq) was fought between the Government of Pakistan and the Tehrik-i-Taliban in late 2007 over control of the Swat District of Pakistan. The battle began on 25 October 2007 and involved the Pakistani Army and TTP-led forces in a fight for control of the Swat district of Pakistan.', 2007, 10, 25, 2007, 12, 8, 'day', '25 October 2007 – 8 December 2007', 37, 'https://en.wikipedia.org/wiki/First_Battle_of_Swat'),
  ('Q517941', '2008 Pakistan earthquake', 'The 2008 Ziarat earthquakes hit the Pakistani province of Balochistan on October 29 with a moment magnitude of 6.4. The US Geological Survey reported that the first earthquake occurred 60 km (37 mi) north of Quetta and 185 km (115 mi) southeast of the Afghanistan city of Kandahar at 04:09 local time (28 October, 23:09 UTC) at a depth of 15 km (9.3 mi), at 30.653°N, 67.323°E. It was followed by another shallower magnitude 6.4 earthquake at a depth of 14 km (8.7 mi) approximately 12 hours after the initial shock, at 30.546°N, 67.447°E. 215 people were confirmed dead.', 2008, 10, 29, NULL, NULL, NULL, 'day', '29 October 2008', 57, 'https://en.wikipedia.org/wiki/2008_Ziarat_earthquakes'),
  ('Q1945485', 'Battle of Bajaur', 'The Battle of Bajaur (English: Operation Lion Heart), also known as Operation Sherdil, was a military campaign in the Bajaur region of Pakistan. It was conducted on 7 August 2008 by the Frontier Corps and Infantry Brigade of Pakistan army.', 2008, 8, 7, 2009, 2, 28, 'day', '7 August 2008 – 28 February 2009', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bajaur'),
  ('Q3477170', 'Second Battle of Swat', 'The Second Battle of Swat, also known as Operation Rah-e-Rast, was a sub-operation of Operation Black Thunderstorm which began in May 2009 and involved the Pakistan Army and Tehrik-i-Taliban Pakistan militants in a fight for control of the Swat district of Pakistan. The First Battle of Swat had ended with a peace agreement, that the government had signed with the Tehrik-i-Taliban Pakistan in February 2009.', 2009, 7, 15, NULL, NULL, NULL, 'day', '15 July 2009', 39, 'https://en.wikipedia.org/wiki/Second_Battle_of_Swat'),
  ('Q333463', '2010 Pakistan flood', 'The 2010 floods in Pakistan began in late July, resulting from heavy monsoon rains in the Khyber Pakhtunkhwa, Sindh, Punjab and, Balochistan provinces of Pakistan, which affected the Indus River basin. Approximately one-fifth of Pakistan''s total land area was affected by the floods, with Khyber Pakhtunkhwa facing the brunt of the damage, with over 90% of all the deaths occurring in that province.', 2010, 7, NULL, NULL, NULL, NULL, 'month', 'July 2010', 67, 'https://en.wikipedia.org/wiki/2010_Pakistan_floods'),
  ('Q19085', 'killing of Osama bin Laden', 'On May 2, 2011, the United States conducted Operation Neptune Spear, in which SEAL Team Six shot and killed Osama bin Laden at his "Waziristan Haveli" in Abbottabad, Pakistan. Bin Laden, who founded al-Qaeda and orchestrated the September 11 attacks, had been the subject of a United States military manhunt since the beginning of the war in Afghanistan, but escaped to Pakistan—allegedly with Pakistani support—during or after the Battle of Tora Bora in December 2001.', 2011, 5, 2, NULL, NULL, NULL, 'day', '2 May 2011', 69, 'https://en.wikipedia.org/wiki/Killing_of_Osama_bin_Laden'),
  ('Q1348836', '2011 Pakistan earthquake', 'The 2011 Dalbandin earthquake occurred on 19 January at 01:23 a.m. local time with a moment magnitude of Mw 7.2 and a maximum Mercalli intensity of VII (Very strong).', 2011, 1, 19, NULL, NULL, NULL, 'day', '19 January 2011', 50, 'https://en.wikipedia.org/wiki/2011_Dalbandin_earthquake'),
  ('Q2986415', '2011 Sindh floods', 'The 2011 Sindh floods was the highest-ever recorded rainfall between 11 August 2011, and 14 September 2011 in Sindh Province, Pakistan. Heavy rainfall was the main cause of the 2011 Sindh floods.', 2011, 8, 11, NULL, NULL, NULL, 'day', '11 August 2011', 39, 'https://en.wikipedia.org/wiki/2011_Sindh_floods'),
  ('Q29489', 'reactions to Innocence of Muslims', 'The release of the anti-Islamic short film Innocence of Muslims triggered numerous demonstrations across North Africa, the Middle East and South Asia. On September 11, 2012, dozens of protestors scaled the walls and entered the courtyard of the U.S. embassy in Cairo, Egypt.', 2012, 9, NULL, NULL, NULL, NULL, 'month', 'September 2012', 61, 'https://en.wikipedia.org/wiki/Reactions_to_Innocence_of_Muslims'),
  ('Q855050', 'Bhoja Air Flight 213', 'Bhoja Air Flight 213 was a domestic scheduled passenger flight operated by Pakistani private airline Bhoja Air from Karachi to Islamabad. On 20 April 2012, the Boeing 737-200 aircraft serving the route crashed in bad weather during the final approach, killing all 121 passengers and 6 crew on board.', 2012, 4, 20, NULL, NULL, NULL, 'day', '20 April 2012', 65, 'https://en.wikipedia.org/wiki/Bhoja_Air_Flight_213'),
  ('Q14503653', '2013 Afghanistan–Pakistan floods', 'In August 2013, Pakistan and eastern Afghanistan experienced heavy rain that led to flash flooding. More than 180 died as a result of the floods.', 2013, 8, NULL, NULL, NULL, NULL, 'month', 'August 2013', 43, 'https://en.wikipedia.org/wiki/2013_Pakistan%E2%80%93Afghanistan_floods'),
  ('Q14944216', '2013 Balochistan earthquakes', 'The 2013 Balochistan earthquakes were the deadliest to affect Pakistan since 2005. The mainshock, occurring on 24 September, had a moment magnitude of 7.8 and maximum Mercalli intensity of IX (Violent).', 2013, 9, 24, NULL, NULL, NULL, 'day', '24 September 2013', 59, 'https://en.wikipedia.org/wiki/2013_Balochistan_earthquakes'),
  ('Q18641076', '2014 Peshawar school attack', 'On 16 December 2014, six gunmen affiliated with the Tehrik-i-Taliban Pakistan (TTP) conducted a terrorist attack on the Army Public School in the northwestern Pakistani city of Peshawar. The terrorists, all of whom were foreign nationals, comprising one Chechen, three Arabs and two Afghans, entered the school and opened fire on school staff and children, killing 149 people including 132 schoolchildren ranging between eight and eighteen years of age, making it the world''s eighth deadliest school massacre.', 2014, 12, 16, NULL, NULL, NULL, 'day', '16 December 2014', 70, 'https://en.wikipedia.org/wiki/2014_Peshawar_school_massacre'),
  ('Q21201293', '2015 Hindu Kush earthquake', 'The October 2015 Hindu Kush earthquake was a magnitude 7.5 earthquake that struck South Asia on 26 October 2015, at 13:39 AFT (14:09 PKT; 14:39 IST; 09:09 UTC) with the epicenter 45 km north of Kuran wa Munjan, Afghanistan, at a depth of 231.0 km. By 5 November, it was estimated that at least 399 people were killed, mostly in Pakistan.', 2015, 10, 26, NULL, NULL, NULL, 'day', '26 October 2015', 67, 'https://en.wikipedia.org/wiki/October_2015_Hindu_Kush_earthquake'),
  ('Q100021', 'PIA Flight 661', 'Pakistan International Airlines Flight 661 was a Pakistani domestic passenger flight from Chitral to Islamabad, operated by Pakistan''s flag carrier Pakistan International Airlines. On 7 December 2016, the aircraft serving the route, an ATR 42-500 twin-turboprop, crashed near Havelian following an engine failure.', 2016, 12, 7, NULL, NULL, NULL, 'day', '7 December 2016', 65, 'https://en.wikipedia.org/wiki/Pakistan_International_Airlines_Flight_661'),
  ('Q27554442', '2016 Quetta police station attack', 'On 24 October 2016, three heavily armed terrorists carried out an attack on the Balochistan police training college in Quetta, Pakistan, killing 61 cadets and injuring more than 165 others. The Islamic State of Iraq and the Levant – Khorasan Province claimed responsibility for the attack, and Pakistan-based Lashkar-e-Jhangvi claimed to have collaborated with them.', 2016, 10, 24, NULL, NULL, NULL, 'day', '24 October 2016', 41, 'https://en.wikipedia.org/wiki/2016_Quetta_police_training_college_attack'),
  ('Q1260080', 'drone strikes in Pakistan', 'Between 2004 and 2018, the United States government attacked thousands of targets in northwest Pakistan using unmanned aerial vehicles (drones) operated by the United States Air Force under the operational control of the Central Intelligence Agency''s Special Activities Division during the war on terror. Most of these attacks were on targets in the Federally Administered Tribal Areas (now part of the Khyber Pakhtunkhwa province) along the Afghan border in northwest Pakistan.', 2018, 1, 24, NULL, NULL, NULL, 'day', '24 January 2018', 50, 'https://en.wikipedia.org/wiki/American_drone_strikes_in_Pakistan'),
  ('Q61896704', '2019 India–Pakistan border skirmishes', 'In the aftermath of the Pulwama attack on 14 February 2019, a standoff emerged between India and Pakistan consisting of cross-border airstrikes and exchanges of gunfire between India and Pakistan across the de facto border in the disputed Kashmir region, which is subject to extensive territorial claims by both countries. The Pulwama attack in Jammu and Kashmir had killed 40 Indian Central Reserve Police Force personnel.', 2019, 2, 14, NULL, NULL, NULL, 'day', '14 February 2019', 63, 'https://en.wikipedia.org/wiki/2019_India%E2%80%93Pakistan_border_skirmishes'),
  ('Q68512664', '2019 Kashmir earthquake', 'The 2019 Kashmir earthquake struck regions of Pakistan with an epicentre in Azad Kashmir on 24 September at 16:02 local time (11:02 UTC). It had a magnitude of 5.4 Mww and a maximum felt intensity of VII (Very strong) on the Modified Mercalli intensity scale or VIII (Heavily damaging) on the European macroseismic scale.', 2019, 9, 24, NULL, NULL, NULL, 'day', '24 September 2019', 52, 'https://en.wikipedia.org/wiki/2019_Kashmir_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q96745476', '2020 Pakistan Stock Exchange attack', 'On 29 June 2020, Balochistan Liberation Army (BLA) militants attacked the Pakistan Stock Exchange (PSX) building in Karachi with grenades and by firing indiscriminately. At least three security guards and a police sub-inspector were killed, while seven people were injured during the attack.', 2020, 6, 29, NULL, NULL, NULL, 'day', '29 June 2020', 45, 'https://en.wikipedia.org/wiki/Pakistan_Stock_Exchange_attack'),
  ('Q108822258', '2021 Balochistan earthquake', 'An earthquake struck Pakistan''s province of Balochistan near the city of Harnai on 7 October 2021. The moment magnitude 5.9 Mww quake struck in the early morning at 03:01 local time, killing at least 42 people and injuring 300 others.', 2021, 10, 7, NULL, NULL, NULL, 'day', '7 October 2021', 55, 'https://en.wikipedia.org/wiki/2021_Balochistan_earthquake'),
  ('Q111088408', '2022 Peshawar mosque bombing', 'On 4 March 2022, the Islamic State – Khorasan Province attacked a Shia mosque at Qissa Khwani Bazaar in Peshawar, Pakistan. The suicide attack, carried out by an Afghan man who was a long-term resident of Pakistan, killed at least 63 people and injured another 196.', 2022, 3, 4, NULL, NULL, NULL, 'day', '4 March 2022', 56, 'https://en.wikipedia.org/wiki/2022_Peshawar_mosque_attack'),
  ('Q112666390', 'June 2022 Afghanistan earthquake', 'A 4.0-kilometre (2.5 mi) deep earthquake measuring a magnitude (Mw) of 6.2 struck southeastern Afghanistan on 22 June 2022 at 01:24:36 AFT (on 21 June 2022 at 20:54:36 UTC). The earthquake had a maximum Modified Mercalli intensity of IX (Violent).', 2022, 6, 22, NULL, NULL, NULL, 'day', '22 June 2022', 66, 'https://en.wikipedia.org/wiki/June_2022_Afghanistan_earthquake'),
  ('Q121031981', '2023 Khar bombing', 'On 30 July 2023, the Islamic State – Khorasan Province carried out a suicide bombing at a Jamiat Ulema-e-Islam (F) rally in Khar, Bajaur District, Khyber Pakhtunkhwa, Pakistan, killing at least 63 people and injuring nearly 200 others.', 2023, 7, 30, NULL, NULL, NULL, 'day', '30 July 2023', 45, 'https://en.wikipedia.org/wiki/2023_Khar_bombing'),
  ('Q124450799', '2024 Balochistan bombings', 'On 7 February 2024, twin bombings killed at least 30 people in Balochistan Province of Pakistan, targeting political campaign offices on the eve of the 2024 general election. At least 40 people were reported injured.', 2024, 2, 7, NULL, NULL, NULL, 'day', '7 February 2024', 41, 'https://en.wikipedia.org/wiki/February_2024_Balochistan_bombings'),
  ('Q135264642', '2025 Pakistan floods', 'The 2025 Pakistan floods were a series of devastating floods triggered by heavy pre-monsoon rains in June 2025 and continuing throughout the monsoon season into September. The disaster primarily affected Khyber Pakhtunkhwa, Punjab, Sindh, Balochistan and Azad Kashmir, causing widespread casualties, infrastructure damage, and mass displacement.', 2025, NULL, NULL, NULL, NULL, NULL, 'year', '2025', 47, 'https://en.wikipedia.org/wiki/2025_Pakistan_floods'),
  ('Q137988475', 'January–February 2026 Balochistan attacks', 'In late January and early February 2026, in a series of coordinated attacks across multiple districts in Balochistan, Baloch insurgents engaged in armed assaults and suicide bombings targeting schools, hospitals, banks, markets, security installations, police stations, a high-security prison, and various civilian areas. These attacks occurred as part of an ongoing insurgency in the Balochistan region, where nationalist and separatist groups are seeking greater autonomy or independence from Pakistan and Iran.', 2026, 1, 31, NULL, NULL, NULL, 'day', '31 January 2026', 48, 'https://en.wikipedia.org/wiki/January%E2%80%93February_2026_Balochistan_attacks'),
  ('Q138025426', '2026 Islamabad suicide bombing', 'On 6 February 2026, a suicide attack occurred at the Khadija Tul Kubra Mosque, a Shia mosque in the Tarlai Kalan area of southeastern Islamabad, Pakistan. The explosion occurred during Friday prayer, killing 31 people and injuring over 169 others.', 2026, 2, 6, NULL, NULL, NULL, 'day', '6 February 2026', 55, 'https://en.wikipedia.org/wiki/2026_Islamabad_mosque_bombing'),
  ('Q138414208', '2026 Afghanistan–Pakistan War', 'Since February 2026, Pakistan and Afghanistan have been engaged in the most sustained cross-border conflict between the two countries since the Taliban''s 2021 return to power in Afghanistan. The conflict began with Pakistani airstrikes on alleged Pakistani Taliban (TTP) and Islamic State – Khorasan Province camps in eastern Afghanistan, and escalated within a week into what Pakistan''s defence minister, Khawaja Asif, called an "open war" fought under the codename Operation Ghazab lil-Haq.', 2026, 2, 21, NULL, NULL, NULL, 'day', '21 February 2026', 71, 'https://en.wikipedia.org/wiki/2026_Afghanistan%E2%80%93Pakistan_war'),
  ('Q138511765', '2026 attack on the United States consulate in Karachi', 'On 1 March 2026, the Consulate General of the United States in Karachi, Pakistan, was targeted by Shia Muslim protesters following strikes on Iran by the US and Israel in which Iranian supreme leader Ayatollah Ali Khamenei was assassinated. As the protesters assaulted the consulate and breached the outer wall, the Marine Security Guards opened fire, killing 10 protesters and injuring over 60.', 2026, 3, 1, NULL, NULL, NULL, 'day', '1 March 2026', 50, 'https://en.wikipedia.org/wiki/2026_attack_on_the_United_States_consulate_in_Karachi'),
  ('Q140459803', 'K2 Airways Flight 1732', 'K2 Airways Flight 1732 was a scheduled international cargo flight operated by K2 Airways from Sharjah International Airport in Sharjah, United Arab Emirates, to Jinnah International Airport in Karachi, Pakistan. On 7 July 2026, the Boeing 737-400 freighter crashed in the Arabian Sea following a reported malfunction of navigation systems..', 2026, 7, 7, NULL, NULL, NULL, 'day', '7 July 2026', 52, 'https://en.wikipedia.org/wiki/K2_Airways_Flight_1732'),
  ('Q140800370', '2026 Broad Peak avalanche', 'On 30 July 2026, an avalanche struck a group of 10 climbers attempting to summit Broad Peak in the Karakoram range of Pakistan. The avalanche occurred at an altitude of about 6,600 m (21,700 ft) on the slope between Camp 2 and Camp 3 and swept all the climbers down the mountain.', 2026, 7, 30, NULL, NULL, NULL, 'day', '30 July 2026', 57, 'https://en.wikipedia.org/wiki/2026_Broad_Peak_avalanche'),
  ('Q141501925', '2026 Kohat attack', 'On 18 September 2026, armed insurgents attacked and occupied the Old Police Lines complex in Kohat, Pakistan. After an initial attack on the Old Police Lines mosque, a battle and clearance operation continued for about 22 hours, resulting in 31 deaths and 103 injuries.', 2026, 9, 18, NULL, NULL, NULL, 'day', '18 September 2026', 48, 'https://en.wikipedia.org/wiki/2026_Kohat_attack');
